import sys, pathlib
from playwright.sync_api import sync_playwright
sys.path.insert(0, str(pathlib.Path(__file__).parent)); import e2e_setup as S
SITE='http://127.0.0.1:8000'; SH=pathlib.Path(__file__).parent/'shots'; res=[]
def check(n,c,d=''): res.append(bool(c)); print(('PASS ' if c else 'FAIL ')+n+('' if c else f' -> {d}'), flush=True)
with sync_playwright() as p:
    br=p.chromium.launch()
    for name,vp in (('desktop',dict(viewport={'width':1440,'height':900})),('mobile',dict(viewport={'width':390,'height':844},is_mobile=True,has_touch=True,device_scale_factor=2))):
        ctx=br.new_context(**vp); S.setup(ctx); pg=ctx.new_page(); errs=[]; pg.on('pageerror',lambda e: errs.append(str(e)))
        pg.goto(SITE+'/index.html'); pg.wait_for_selector('#samsamSignInBtn'); pg.click('#samsamSignInBtn'); pg.wait_for_function("Samsam.isReady()"); pg.wait_for_timeout(1000)
        if name=='desktop': pg.evaluate("Samsam.saveAccumPlan(['SOL','ETH','DOT','ATOM','SUI','LINK','PONS','VTHO'].map((s,i)=>({sym:s,name:s,targetQty:1000,addedAt:'2026-10-1'+i})))"); pg.wait_for_timeout(700)
        pg.goto(SITE+'/accumulation.html'); pg.wait_for_function("Samsam.isReady()"); pg.wait_for_timeout(1500)
        pg.click('#btnCards'); pg.wait_for_timeout(300)
        t=pg.evaluate("document.querySelector('#catPicker .sdd-btn').innerText.replace(/\\s+/g,' ')")
        check(f'{name}: category card shows All Coins ({t})', 'All Coins' in t)
        pg.click('#catPicker .sdd-btn'); pg.wait_for_timeout(300)
        names=pg.evaluate("[...document.querySelectorAll('.sdd-panel.show .sdd-opt > span:not(.sdd-ico):not(.sdd-sub)')].map(l=>l.innerText.trim())")
        check(f'{name}: same 9 categories as main page', names[:10]==['All Coins','Layer 1 Blockchains','Layer 2 Blockchains','AI & DePIN','Layer 0 & Interoperability','Oracles & Middleware','DeFi & RWA','Meme & Utility Tokens','Launchpad','Web3 & Gaming'], names)
        if name=='mobile': check('mobile: bottom sheet', pg.evaluate("document.querySelector('.sdd-panel.show').classList.contains('sheet')"))
        pg.screenshot(path=str(SH/f'accum_cat_{name}_open.png'))
        pg.locator('.sdd-panel.show .sdd-opt:has-text("Layer 0 & Interoperability")').click(); pg.wait_for_timeout(150)
        cs=pg.evaluate("[...document.querySelectorAll('#cardsView .coin-card .ast-sym')].map(e=>e.childNodes[0].textContent.trim())")
        anim=pg.evaluate("document.querySelectorAll('#cardsView .coin-card.slide-up').length")
        check(f'{name}: cards filtered to Layer 0 {cs}', sorted(cs)==['ATOM','DOT'], cs)
        check(f'{name}: filtered cards slide up', anim==len(cs), anim)
        pg.click('#btnTable'); pg.wait_for_timeout(300)
        ts=pg.evaluate("[...document.querySelectorAll('#tableView tbody tr .ast-sym')].map(e=>e.childNodes[0].textContent.trim())")
        check(f'{name}: table keeps the same filter {ts}', sorted(ts)==['ATOM','DOT'], ts)
        v=pg.evaluate("[document.getElementById('catPickerVal').textContent, SamsamFmt.usd(accumPlan.filter(e=>['DOT','ATOM'].includes(e.sym)).reduce((a,e)=>{const r=calcRow(e);return a+r.actualQty*r.currentPrice},0))]")
        check(f'{name}: card value = holdings of that category {v}', v[0]==v[1], v)
        pg.click('#btnCards'); pg.wait_for_timeout(200)
        pg.click('#catPicker .sdd-btn'); pg.wait_for_timeout(250); pg.locator('.sdd-panel.show .sdd-opt:has-text("All Coins")').click(); pg.wait_for_timeout(200)
        pg.locator('#cardsView .cat-tag:text-is("Oracles & Middleware")').first.click(); pg.wait_for_timeout(250)
        lab=pg.evaluate("[catEditModal.classList.contains('show'), ceTitle.innerText, document.querySelector('#catPicker .sdd-label').textContent]")
        check(f'{name}: tapping a coin tag opens Change category for it (like the main page), filter unchanged {lab}', lab == [True, 'Category — LINK', 'All Coins'], lab)
        pg.keyboard.press('Escape'); pg.wait_for_timeout(200)
        pg.mouse.move(1,1); y=pg.evaluate("document.getElementById('catPicker').getBoundingClientRect().top+scrollY-10")
        pg.screenshot(path=str(SH/f'accum_cat_{name}.png'), full_page=True, clip={'x':0,'y':y,'width':vp['viewport']['width'],'height':520})
        check(f'{name}: no JS errors', not errs, errs[:3]); ctx.close()
    br.close()
print(f'{sum(res)}/{len(res)} passed'); sys.exit(0 if all(res) else 1)
